const gh = $('GitHub Trending').first().json;
const repos = Array.isArray(gh) ? gh : (gh.repos || []);
const ghNews = repos.slice(0, 8).map(r => ({
  title: r.name || '無標題',
  summary: r.description || '無描述',
  url: r.html_url || '#',
  source: 'GitHub',
  score: Math.min(Math.floor((r.stars||0)/100), 10),
  tags: [r.language||'開源']
}));
const hn = $('LLM處理').all().map(d => d.json).filter(j => j && j.title).map(j => {
  try {
    const c = typeof j === 'string' ? JSON.parse(j) : j;
    return {title: c.title||'無標題', summary: c.text ? c.text.substring(0,150) : '無描述',
      url: c.url||`https://news.ycombinator.com/item?id=${c.id}`, source: 'Hacker News',
      score: c.score ? Math.min(Math.floor(c.score/10), 10) : 5, tags: ['科技']};
  } catch(e) { return null; }
}).filter(Boolean);
return [{json: {news: [...ghNews, ...hn]}}];

const {news} = $input.first().json;
const kw = {};
news.forEach(item => {
  (item.title + ' ' + item.summary).split(/[\s]+/).forEach(w => {
    if (w.length > 3 && !['https','github','http','www'].includes(w.toLowerCase())) kw[w] = (kw[w]||0) + 1;
  });
});
const top = Object.entries(kw).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([w,c])=>({word:w,count:c}));
return [{json: {trending: top, news}}];

const {news, trending} = $input.first().json;
const now = new Date();
const dateStr = now.toLocaleDateString('zh-TW', {year:'numeric', month:'long', day:'numeric'});
const dateFile = now.toISOString().split('T')[0];
const top3 = news.slice(0,3);
const summary = `今日熱點：${top3.map(n=>n.title).join('、')}。共${news.length}篇。`;
const th = trending.map(t => `<div class="trending-item"><div class="count">${t.count}</div><div class="tag">${t.word}</div></div>`).join('');
function rn(list) { return list.map(n => `<div class="news-item"><span class="score">${n.score||5}分</span><h3><a href="${n.url}" target="_blank">${n.title}</a></h3><p class="desc">${n.summary}</p><div class="meta"><span>📍${n.source}</span></div><div class="tags">${(n.tags||[]).map(t=>`<span class="tag">${t}</span>`).join('')}</div></div>`).join(''); }
