5px}.footer{text-align:center;padding:40px 0;color:#666;font-size:0.85em;border-top:1px solid #222;margin-top:60px}.footer a{color:#00d4ff;text-decoration:none}@media(max-width:600px){body{padding:15px}.header h1{font-size:1.8em}}</style></head><body><div class="container"><header class="header"><div class="emoji">🤖</div><h1>AI Daily</h1><p class="subtitle">每天早 8 點，5 分鐘看懂 AI 與科技圈</p><p class="date">更新於 ${dateStr} · 收錄 ${news.length} 篇</p></header><div class="summary"><h2>📌 今日總結</h2><p>${summary}</p></div><div class="trending"><h2>🔥 今日熱搜</h2><div class="trending-grid">${th}</div></div><div class="news-section"><h2 class="section-title">頭條 · AI 前線</h2>${rn(news.slice(0,5))}</div><div class="news-section" style="margin-top:40px"><h2 class="section-title">🛠️ 工具 · 開發</h2>${rn(news.slice(5,10))}</div><footer class="footer"><p>由 AI 自動生成 · <a href="https://github.com/ming-7065/ai-news-daily">GitHub</a></p><p style="margin-top:10px"><a href="archive.html">📁 過刊列表</a></p></footer></div></body></html>`;
const ah = `<!DOCTYPE html><html lang="zh-TW"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>AI Daily - ${dateStr}</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:#0a0a0f;color:#e5e5e5;min-height:100vh;padding:40px 20px}.container{max-width:900px;margin:0 auto}.header{text-align:center;padding:40px 0;border-bottom:1px solid #222;margin-bottom:40px}.header h1{font-size:2em;margin-bottom:10px}.header .subtitle{color:#888}.news-item{background:#111;border-radius:12px;padding:20px;margin-bottom:20px;border:1px solid #222}.news-item .score{display:inline-block;background:#ff6b6b;color:#fff;padding:3px 10px;border-radius:20px;font-size:0.85em;font-weight:bold}.news-item h3{margin:10px 0;font-size:1.1em}.news-item h3 a{color:inherit;text-decoration:none}.news-item h3 a:hover{color:#00d4ff}.news-item .desc{color:#999;margin:10px 0;line-height:1.6}.news-item .meta{color:#666;font-size:0.85em}.news-item .tags{margin-top:10px}.news-item .tag{display:inline-block;background:#1a1a2e;color:#00d4ff;padding:3px 10px;border-radius:4px;font-size:0.8em;margin-right:5px}.footer{text-align:center;padding:40px 0;color:#666;font-size:0.85em;border-top:1px solid #222;margin-top:60px}.footer a{color:#00d4ff;text-decoration:none}</style></head><body><div class="container"><header class="header"><div class="emoji">🤖</div><h1>AI Daily</h1><p class="subtitle">${dateStr} 完整新聞</p><p class="date">共 ${news.length} 篇</p></header><div class="news-section">${rn(news)}</div><footer class="footer"><p><a href="index.html">← 返回首頁</a> · <a href="https://github.com/ming-7065/ai-news-daily">GitHub</a></p></footer></div></body></html>`;
return [{json: {indexHtml: html, archiveHtml: ah, dateFile, dateStr, newsCount: news.length}}];
